"""Raw STATICCALL and uint256 decoding: original/model/generated bytecode.

A calldata-hashing child gives an independent oracle for selector and argument
encoding. Source guards and decoder guards are observed separately.
"""
import argparse
import random
from pathlib import Path

from eth_abi import encode
from eth_utils import keccak
from .check_legacy_signature_calls import campaign, RESPONSES, MASK
from .check_interface_word_static_call import SENDER, EMPTY

FIXTURE = Path('Contracts/SolidityImportSmoke/LegacyStaticWord.sol')
MODEL = FIXTURE.with_name('LegacyStaticWordModel.lean')


def transactions(seed, caller, accounts, random_cases):
    rng = random.Random(seed)
    calls, expectations = [], {}

    def child(target, account):
        if target not in accounts:
            return True, b''
        value, failed, length, mask = RESPONSES[accounts.index(target)]
        payload = keccak(text='read(address)')[:4] + encode(['address'], [account])
        word = value ^ (int.from_bytes(keccak(payload), 'big') & mask)
        memory = word.to_bytes(32, 'big') + bytes(32) + (128).to_bytes(32, 'big') + bytes(32) + payload
        return not failed, memory.ljust(length, b'\0')[:length]

    def add(signature, values, expected):
        types = signature[signature.index('(')+1:-1].split(',')
        payload = encode(types, values)
        ident = str(len(calls))
        calls.append({'id': ident, 'function': signature.split('(')[0],
            'args': [int.from_bytes(payload[i:i+32], 'big') for i in range(0, len(payload), 32)],
            'sender': SENDER, 'target': caller, 'value': '0x0',
            'data': '0x' + keccak(text=signature)[:4].hex() + payload.hex(),
            'timestamp': 1000000100 + len(calls), 'blockNumber': len(accounts)+2+len(calls)})
        expectations[ident] = expected

    def words(*values):
        return 'ok', '0x' + encode(['uint256'] * len(values), list(map(int, values))).hex()

    def decoded(target, account):
        ok, data = child(target, account)
        return words(int.from_bytes(data[:32], 'big')) if ok and len(data) >= 32 else ('revert', '0x')

    addresses = [caller, '0x' + 'ff' * 20, '0x' + '00' * 20]
    addresses += ['0x' + rng.randbytes(20).hex() for _ in range(random_cases)]
    for target in [*accounts, EMPTY, SENDER]:
        for account in addresses:
            want = decoded(target, account)
            for method in ['word', 'decoded']:
                add(method + '(address,address)', [target, account], want)
            ok, data = child(target, account)
            # ABI-v1 encodeWithSelector advances by 32 + 36 without alignment.
            header = 196 if data else 96
            free = 228 + 32 * ((len(data)+31)//32) if data else 196
            add('inspect(address,address)', [target, account], words(ok, len(data), header, free))
            amount = int.from_bytes(data[:32], 'big')
            for minimum in sorted({0, amount, min(amount + 1, MASK)}):
                expected = want if want[0] == 'revert' else words(1) if amount >= minimum else (
                    'revert', '0x' + (keccak(text='Error(string)')[:4] + encode(['string'], ['insufficient'])).hex())
                add('atLeast(address,address,uint256)', [target, account, minimum], expected)
        add('selfWord(address)', [target], decoded(target, caller))
        first = accounts[3]  # calldata-sensitive successful word
        a, x = child(first, caller)
        b, y = child(target, caller)
        add('inspectPair(address,address,address)', [first, target, caller], words(a, b, len(x), len(y)))
        want = decoded(target, caller)
        pair = words(int.from_bytes(x[:32], 'big'), int.from_bytes(y[:32], 'big')) if want[0] == 'ok' else want
        add('twice(address,address,address)', [first, target, caller], pair)
    return calls, [], expectations


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--optimized', action='store_true')
    parser.add_argument('--context', type=int, choices=(0, 1, 2), default=0)
    parser.add_argument('--random-cases', type=int, default=1)
    args = parser.parse_args()
    return campaign(args.output, optimized=args.optimized, context=args.context,
                    random_cases=args.random_cases, fixture=FIXTURE, driver_template=MODEL,
                    make_transactions=transactions)


if __name__ == '__main__':
    raise SystemExit(main())
